   for(let index=0;index<batch.length;index++){const row=batch[index],key=ids[index],prior=groups.get(key);if(prior&&!same(prior.identity,row.identity))invalid();if(prior)prior.quantity+=row.quantity;else groups.set(key,{identity:row.identity,quantity:row.quantity})}
